    (65, 'garam_wood@linkup.test', '황가람', 'garam.wood', '/uploads/profiles/images5.jpg', '나무를 다듬어 오래 쓰는 생활 가구를 만듭니다.', 'ROLE_CREATOR', 0, NULL, 4, 10, '2026-07-22 17:31:00', '2026-07-22 17:31:00'),
    (66, 'yurim_dance@linkup.test', '안유림', 'yurim.dance', '/uploads/profiles/images6.jpg', '누구나 따라 할 수 있는 춤과 스트레칭을 알려드려요.', 'ROLE_CREATOR', 0, NULL, 3, 10, '2026-07-23 01:38:00', '2026-07-23 01:38:00'),
    (67, 'junho_history@linkup.test', '송준호', 'junho.history', '/uploads/profiles/images7.jpg', '오늘과 닿아 있는 흥미로운 역사 이야기를 전합니다.', 'ROLE_CREATOR', 0, NULL, 5, 10, '2026-07-23 09:45:00', '2026-07-23 09:45:00'),
    (68, 'bomin_sewing@linkup.test', '전보민', 'bomin.sewing', '/uploads/profiles/images8.jpg', '옷을 고쳐 입고 직접 만드는 즐거움을 기록해요.', 'ROLE_CREATOR', 0, NULL, 4, 10, '2026-07-23 17:52:00', '2026-07-23 17:52:00'),
    (69, 'jisoo_green@linkup.test', '홍지수', 'jisoo.green', '/uploads/profiles/images9.jpg', '쓰레기를 줄이는 현실적인 생활 습관을 실험합니다.', 'ROLE_CREATOR', 0, NULL, 4, 10, '2026-07-24 01:06:00', '2026-07-24 01:06:00'),
    (70, 'taekyung_photo@linkup.test', '고태경', 'taekyung.photo', '/uploads/profiles/images10.jpg', '스마트폰으로도 좋은 사진을 남기는 방법을 나눕니다.', 'ROLE_CREATOR', 0, NULL, 5, 10, '2026-07-24 09:13:00', '2026-07-24 09:13:00'),
    (71, 'yena_makeup@linkup.test', '문예나', 'yena.makeup', '/uploads/profiles/images1.jpg', '피부 표현부터 색조 조합까지 차근차근 알려드려요.', 'ROLE_USER', 0, NULL, 7, 10, '2026-07-24 17:20:00', '2026-07-24 17:20:00'),
    (72, 'hyunsu_cooking@linkup.test', '양현수', 'hyunsu.cooking', '/uploads/profiles/images2.jpg', '한 그릇으로 든든한 요리와 주방의 작은 요령들.', 'ROLE_USER', 0, NULL, 5, 10, '2026-07-25 01:27:00', '2026-07-25 01:27:00'),
    (73, 'seoa_write@linkup.test', '손서아', 'seoa.write', '/uploads/profiles/images3.jpg', '쓰고 싶은 사람을 위한 문장 연습과 창작 노트를 나눕니다.', 'ROLE_USER', 0, NULL, 3, 10, '2026-07-25 09:34:00', '2026-07-25 09:34:00'),
    (74, 'doha_musiclab@linkup.test', '배도하', 'doha.musiclab', '/uploads/profiles/images4.jpg', '방 안에서 음악을 만들며 배운 것들을 기록합니다.', 'ROLE_USER', 0, NULL, 7, 10, '2026-07-25 17:41:00', '2026-07-25 17:41:00'),
    (75, 'chaerin_fitness@linkup.test', '백채린', 'chaerin.fitness', '/uploads/profiles/images5.jpg', '기구 없이 시작하는 홈트레이닝과 회복 루틴.', 'ROLE_USER', 0, NULL, 5, 10, '2026-07-26 01:48:00', '2026-07-26 01:48:00'),
    (76, 'junhyuk_car@linkup.test', '허준혁', 'junhyuk.car', '/uploads/profiles/images6.jpg', '자동차 관리의 기본과 주말 드라이브 코스를 소개합니다.', 'ROLE_USER', 0, NULL, 3, 10, '2026-07-26 09:02:00', '2026-07-26 09:02:00'),
    (77, 'sujin_museum@linkup.test', '남수진', 'sujin.museum', '/uploads/profiles/images7.jpg', '전시를 천천히 보고 작품 뒤의 이야기를 전합니다.', 'ROLE_USER', 0, NULL, 4, 10, '2026-07-26 17:09:00', '2026-07-26 17:09:00'),
    (78, 'yuchan_boardgame@linkup.test', '심유찬', 'yuchan.boardgame', '/uploads/profiles/images8.jpg', '친구들과 즐기기 좋은 보드게임을 직접 플레이하고 리뷰합니다.', 'ROLE_USER', 0, NULL, 5, 10, '2026-07-27 01:16:00', '2026-07-27 01:16:00'),
    (79, 'ayoung_dessert@linkup.test', '노아영', 'ayoung.dessert', '/uploads/profiles/images9.jpg', '작은 주방에서 만드는 계절 디저트와 베이킹 팁.', 'ROLE_USER', 0, NULL, 3, 10, '2026-07-27 09:23:00', '2026-07-27 09:23:00'),
    (80, 'mingyu_science@linkup.test', '하민규', 'mingyu.science', '/uploads/profiles/images10.jpg', '어려운 과학 이야기를 일상의 언어로 쉽게 풀어냅니다.', 'ROLE_USER', 0, NULL, 5, 10, '2026-07-27 17:30:00', '2026-07-27 17:30:00');

INSERT INTO post (id, member_id, content, file_url, like_count, subscriber_only, hidden, created_at, updated_at) VALUES
    (1, 1, '오늘 산 능선은 구름이 낮게 걸려 있었다. 같은 길도 날씨가 바뀌면 완전히 다른 풍경이 된다.', NULL, 2, FALSE, FALSE, '2026-08-20 12:11:00', '2026-08-20 12:11:00'),
    (2, 2, '시장표 채소로 만든 따뜻한 수프. 냉장고를 비우는 날에도 꽤 근사한 한 그릇이 된다.', NULL, 2, FALSE, FALSE, '2026-08-20 15:22:00', '2026-08-20 15:22:00'),
    (3, 2, '골목 끝에서 만난 작은 공원. 벤치 하나와 오래된 나무 그늘만으로 충분히 좋은 쉼표였다.', NULL, 2, FALSE, FALSE, '2026-08-20 18:33:00', '2026-08-20 18:33:00'),
    (4, 39, '새벽 호수는 생각보다 조용했다. 물안개가 걷히는 시간을 천천히 담아두었다.', NULL, 1, FALSE, FALSE, '2026-08-20 21:44:00', '2026-08-20 21:44:00'),
    (5, 20, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 6, FALSE, FALSE, '2026-08-21 00:08:00', '2026-08-21 00:08:00'),
    (6, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-21 03:19:00', '2026-08-21 03:19:00'),
    (7, 7, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-08-21 06:30:00', '2026-08-21 06:30:00'),
    (8, 9, '맑은 날보다 흐린 날의 풍경이 더 오래 남을 때가 있다. 오늘은 그런 오후였다.', NULL, 2, FALSE, FALSE, '2026-08-21 09:41:00', '2026-08-21 09:41:00'),
    (9, 2, '동물 사진은 기다리는 시간이 절반이다. 오늘은 눈을 마주친 짧은 순간이 가장 좋았다.', NULL, 2, FALSE, FALSE, '2026-08-21 12:05:00', '2026-08-21 12:05:00'),
    (10, 2, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다.', NULL, 7, FALSE, FALSE, '2026-08-21 15:16:00', '2026-08-21 15:16:00'),
    (11, 38, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 10, FALSE, FALSE, '2026-08-21 18:27:00', '2026-08-21 18:27:00'),
    (12, 5, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-21 21:38:00', '2026-08-21 21:38:00'),
    (13, 2, '디저트는 단맛보다 온도가 중요할 때가 있다. 차갑게 식힌 크림과 따뜻한 과일이 잘 맞았다.', NULL, 1, FALSE, FALSE, '2026-08-22 00:02:00', '2026-08-22 00:02:00'),
    (14, 79, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 2, FALSE, FALSE, '2026-08-22 03:13:00', '2026-08-22 03:13:00'),
    (15, 2, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 8, FALSE, FALSE, '2026-08-22 06:24:00', '2026-08-22 06:24:00'),
    (16, 19, '낯선 동네의 언덕길을 올랐다. 지붕과 전선, 먼 산이 한 장면 안에 차분히 들어왔다.', NULL, 1, FALSE, FALSE, '2026-08-22 09:35:00', '2026-08-22 09:35:00'),
    (17, 28, '가을빛이 들기 시작한 숲길. 발걸음을 늦추니 잎 사이의 작은 소리까지 들렸다.', NULL, 2, FALSE, FALSE, '2026-08-22 12:46:00', '2026-08-22 12:46:00'),
    (18, 5, '평일 저녁 20분 요리 루틴을 파일에 담았습니다. 미리 손질할 재료와 마지막에 넣을 향신료를 나눠두면 맛이 안정됩니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-22 15:10:00', '2026-08-22 15:10:00'),
    (19, 44, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 20, FALSE, FALSE, '2026-08-22 18:21:00', '2026-08-22 18:21:00'),
    (20, 2, '작은 새들이 나뭇가지 사이를 바쁘게 오갔다. 잠깐 멈춰 보니 공원은 생각보다 분주했다.', NULL, 5, FALSE, FALSE, '2026-08-22 21:32:00', '2026-08-22 21:32:00'),
    (21, 2, '오늘 산 능선은 구름이 낮게 걸려 있었다. 같은 길도 날씨가 바뀌면 완전히 다른 풍경이 된다.', NULL, 2, FALSE, FALSE, '2026-08-23 00:43:00', '2026-08-23 00:43:00'),
    (22, 6, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 11, FALSE, FALSE, '2026-08-23 03:07:00', '2026-08-23 03:07:00'),
    (23, 17, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-08-23 06:18:00', '2026-08-23 06:18:00'),
    (24, 7, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-23 09:29:00', '2026-08-23 09:29:00'),
    (25, 5, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 6, FALSE, FALSE, '2026-08-23 12:40:00', '2026-08-23 12:40:00'),
    (26, 43, '비 오는 날에는 국물이 먼저 생각난다. 오래 끓이지 않아도 깊게 느껴지는 조합을 찾았다.', NULL, 2, FALSE, FALSE, '2026-08-23 15:04:00', '2026-08-23 15:04:00'),
    (27, 27, '동물 사진은 기다리는 시간이 절반이다. 오늘은 눈을 마주친 짧은 순간이 가장 좋았다.', NULL, 2, FALSE, FALSE, '2026-08-23 18:15:00', '2026-08-23 18:15:00'),
    (28, 2, '맑은 날보다 흐린 날의 풍경이 더 오래 남을 때가 있다. 오늘은 그런 오후였다.', NULL, 1, FALSE, FALSE, '2026-08-23 21:26:00', '2026-08-23 21:26:00'),
    (29, 4, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 2, FALSE, FALSE, '2026-08-24 00:37:00', '2026-08-24 00:37:00'),
    (30, 20, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 7, TRUE, FALSE, '2026-08-24 03:01:00', '2026-08-24 03:01:00'),
    (31, 25, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-08-24 06:12:00', '2026-08-24 06:12:00'),
    (32, 34, '해 질 무렵 바닷가를 걸었다. 파도 소리가 크지 않아서 오히려 오래 기억에 남는다.', NULL, 2, FALSE, FALSE, '2026-08-24 09:23:00', '2026-08-24 09:23:00'),
    (33, 2, '골목 끝에서 만난 작은 공원. 벤치 하나와 오래된 나무 그늘만으로 충분히 좋은 쉼표였다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 12, FALSE, FALSE, '2026-08-24 12:34:00', '2026-08-24 12:34:00'),
    (34, 49, '디저트는 단맛보다 온도가 중요할 때가 있다. 차갑게 식힌 크림과 따뜻한 과일이 잘 맞았다.', NULL, 1, FALSE, FALSE, '2026-08-24 15:45:00', '2026-08-24 15:45:00'),
    (35, 2, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 8, FALSE, FALSE, '2026-08-24 18:09:00', '2026-08-24 18:09:00'),
    (36, 5, '구독자분들께 자주 쓰는 장보기 리스트와 보관 팁을 파일로 올렸습니다. 남는 재료 없이 3일 식단으로 이어지게 구성했습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-24 21:20:00', '2026-08-24 21:20:00'),
    (37, 13, '시장표 채소로 만든 따뜻한 수프. 냉장고를 비우는 날에도 꽤 근사한 한 그릇이 된다.', NULL, 28, FALSE, FALSE, '2026-08-25 00:31:00', '2026-08-25 00:31:00'),
    (38, 24, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 18, FALSE, FALSE, '2026-08-25 03:42:00', '2026-08-25 03:42:00'),
    (39, 2, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 2, FALSE, FALSE, '2026-08-25 06:06:00', '2026-08-25 06:06:00'),
    (40, 2, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다.', NULL, 5, FALSE, FALSE, '2026-08-25 09:17:00', '2026-08-25 09:17:00'),
    (41, 48, '오늘 산 능선은 구름이 낮게 걸려 있었다. 같은 길도 날씨가 바뀌면 완전히 다른 풍경이 된다.', NULL, 2, FALSE, FALSE, '2026-08-25 12:28:00', '2026-08-25 12:28:00'),
    (42, 5, '혼자 떠나는 짧은 여행 준비 팁을 정리했습니다. 이동 동선, 배터리, 비상 경로까지 실제로 도움이 됐던 내용만 남겼어요. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-25 15:39:00', '2026-08-25 15:39:00'),
    (43, 2, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-08-25 18:03:00', '2026-08-25 18:03:00'),
    (44, 12, '새벽 호수는 생각보다 조용했다. 물안개가 걷히는 시간을 천천히 담아두었다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 13, FALSE, FALSE, '2026-08-25 21:14:00', '2026-08-25 21:14:00'),
    (45, 2, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 6, FALSE, FALSE, '2026-08-26 00:25:00', '2026-08-26 00:25:00'),
    (46, 31, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 1, FALSE, FALSE, '2026-08-26 03:36:00', '2026-08-26 03:36:00'),
    (47, 40, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-08-26 06:00:00', '2026-08-26 06:00:00'),
    (48, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-08-26 09:11:00', '2026-08-26 09:11:00'),
    (49, 2, '작은 여행의 기준은 멀리가 아니라 오래 바라볼 장면이 있는가인 것 같다.', NULL, 1, FALSE, FALSE, '2026-08-26 12:22:00', '2026-08-26 12:22:00'),
