    (96, 5, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-01 09:22:00', '2026-09-01 09:22:00'),
    (97, 40, '가을빛이 들기 시작한 숲길. 발걸음을 늦추니 잎 사이의 작은 소리까지 들렸다.', NULL, 1, FALSE, FALSE, '2026-09-01 12:33:00', '2026-09-01 12:33:00'),
    (98, 47, '토마토와 바질을 넣어 가볍게 만든 점심. 재료가 단순할수록 간을 천천히 맞추는 게 중요했다.', NULL, 2, FALSE, FALSE, '2026-09-01 15:44:00', '2026-09-01 15:44:00'),
    (99, 2, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 13, FALSE, FALSE, '2026-09-01 18:08:00', '2026-09-01 18:08:00'),
    (100, 5, '햇살 아래 잠든 강아지를 보니 하루가 조금 부드러워졌다. 평온한 장면은 설명이 적을수록 좋다.', NULL, 5, FALSE, FALSE, '2026-09-01 21:19:00', '2026-09-01 21:19:00'),
    (101, 11, '오븐에서 갓 나온 빵 냄새는 언제나 과하다 싶을 만큼 좋다. 오늘은 실패 없이 잘 부풀었다.', NULL, 2, FALSE, FALSE, '2026-09-02 00:30:00', '2026-09-02 00:30:00'),
    (102, 5, '평일 저녁 20분 요리 루틴을 파일에 담았습니다. 미리 손질할 재료와 마지막에 넣을 향신료를 나눠두면 맛이 안정됩니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-02 03:41:00', '2026-09-02 03:41:00'),
    (103, 30, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-09-02 06:05:00', '2026-09-02 06:05:00'),
    (104, 39, '새벽 호수는 생각보다 조용했다. 물안개가 걷히는 시간을 천천히 담아두었다.', NULL, 2, FALSE, FALSE, '2026-09-02 09:16:00', '2026-09-02 09:16:00'),
    (105, 20, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 6, FALSE, FALSE, '2026-09-02 12:27:00', '2026-09-02 12:27:00'),
    (106, 2, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 1, FALSE, FALSE, '2026-09-02 15:38:00', '2026-09-02 15:38:00'),
    (107, 7, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-09-02 18:02:00', '2026-09-02 18:02:00'),
    (108, 5, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-02 21:13:00', '2026-09-02 21:13:00'),
