    (110, 2, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 9, FALSE, FALSE, '2026-09-03 03:35:00', '2026-09-03 03:35:00'),
    (111, 2, '동물 사진은 기다리는 시간이 절반이다. 오늘은 눈을 마주친 짧은 순간이 가장 좋았다.', NULL, 25, FALSE, FALSE, '2026-09-03 06:46:00', '2026-09-03 06:46:00'),
    (112, 45, '해 질 무렵 바닷가를 걸었다. 파도 소리가 크지 않아서 오히려 오래 기억에 남는다.', NULL, 1, FALSE, FALSE, '2026-09-03 09:10:00', '2026-09-03 09:10:00'),
    (113, 2, '골목 끝에서 만난 작은 공원. 벤치 하나와 오래된 나무 그늘만으로 충분히 좋은 쉼표였다.', NULL, 2, FALSE, FALSE, '2026-09-03 12:21:00', '2026-09-03 12:21:00'),
    (114, 7, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 17, TRUE, FALSE, '2026-09-03 15:32:00', '2026-09-03 15:32:00'),
