    (153, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-08 12:38:00', '2026-09-08 12:38:00'),
    (154, 39, '토마토와 바질을 넣어 가볍게 만든 점심. 재료가 단순할수록 간을 천천히 맞추는 게 중요했다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 13, FALSE, FALSE, '2026-09-08 15:02:00', '2026-09-08 15:02:00'),
    (155, 20, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 8, FALSE, FALSE, '2026-09-08 18:13:00', '2026-09-08 18:13:00'),
    (156, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다. 실제로 쓰는 메모 형식 그대로라 저장해두고 보기 좋습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-08 21:24:00', '2026-09-08 21:24:00'),
    (157, 80, '오븐에서 갓 나온 빵 냄새는 언제나 과하다 싶을 만큼 좋다. 오늘은 실패 없이 잘 부풀었다.', NULL, 1, FALSE, FALSE, '2026-09-09 00:35:00', '2026-09-09 00:35:00'),
    (158, 9, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 2, FALSE, FALSE, '2026-09-09 03:46:00', '2026-09-09 03:46:00'),
    (159, 2, '작은 여행의 기준은 멀리가 아니라 오래 바라볼 장면이 있는가인 것 같다.', NULL, 2, FALSE, FALSE, '2026-09-09 06:10:00', '2026-09-09 06:10:00'),
    (160, 2, '햇살 아래 잠든 강아지를 보니 하루가 조금 부드러워졌다. 평온한 장면은 설명이 적을수록 좋다.', NULL, 5, FALSE, FALSE, '2026-09-09 09:21:00', '2026-09-09 09:21:00'),
    (161, 38, '오늘 산 능선은 구름이 낮게 걸려 있었다. 같은 길도 날씨가 바뀌면 완전히 다른 풍경이 된다.', NULL, 2, FALSE, FALSE, '2026-09-09 12:32:00', '2026-09-09 12:32:00'),
    (162, 5, '평일 저녁 20분 요리 루틴을 파일에 담았습니다. 미리 손질할 재료와 마지막에 넣을 향신료를 나눠두면 맛이 안정됩니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-09 15:43:00', '2026-09-09 15:43:00'),
    (163, 2, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-09-09 18:07:00', '2026-09-09 18:07:00'),
    (164, 79, '새벽 호수는 생각보다 조용했다. 물안개가 걷히는 시간을 천천히 담아두었다.', NULL, 2, FALSE, FALSE, '2026-09-09 21:18:00', '2026-09-09 21:18:00'),
