    (208, 9, '맑은 날보다 흐린 날의 풍경이 더 오래 남을 때가 있다. 오늘은 그런 오후였다.', NULL, 1, FALSE, FALSE, '2026-09-15 09:32:00', '2026-09-15 09:32:00'),
    (209, 21, '작은 여행의 기준은 멀리가 아니라 오래 바라볼 장면이 있는가인 것 같다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 21, FALSE, FALSE, '2026-09-15 12:43:00', '2026-09-15 12:43:00'),
    (210, 5, '혼자 떠나는 짧은 여행 준비 팁을 정리했습니다. 이동 동선, 배터리, 비상 경로까지 실제로 도움이 됐던 내용만 남겼어요. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 7, TRUE, FALSE, '2026-09-15 15:07:00', '2026-09-15 15:07:00'),
    (211, 38, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-09-15 18:18:00', '2026-09-15 18:18:00'),
    (212, 45, '해 질 무렵 바닷가를 걸었다. 파도 소리가 크지 않아서 오히려 오래 기억에 남는다.', NULL, 2, FALSE, FALSE, '2026-09-15 21:29:00', '2026-09-15 21:29:00'),
    (213, 2, '골목 끝에서 만난 작은 공원. 벤치 하나와 오래된 나무 그늘만으로 충분히 좋은 쉼표였다.', NULL, 2, FALSE, FALSE, '2026-09-16 00:40:00', '2026-09-16 00:40:00'),
    (214, 79, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 1, FALSE, FALSE, '2026-09-16 03:04:00', '2026-09-16 03:04:00'),
    (215, 2, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 8, FALSE, FALSE, '2026-09-16 06:15:00', '2026-09-16 06:15:00'),
    (216, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-16 09:26:00', '2026-09-16 09:26:00'),
    (217, 28, '가을빛이 들기 시작한 숲길. 발걸음을 늦추니 잎 사이의 작은 소리까지 들렸다.', NULL, 1, FALSE, FALSE, '2026-09-16 12:37:00', '2026-09-16 12:37:00'),
    (218, 36, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 2, FALSE, FALSE, '2026-09-16 15:01:00', '2026-09-16 15:01:00'),
    (219, 2, '동물 사진은 기다리는 시간이 절반이다. 오늘은 눈을 마주친 짧은 순간이 가장 좋았다.', NULL, 2, FALSE, FALSE, '2026-09-16 18:12:00', '2026-09-16 18:12:00'),
    (220, 2, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 9, FALSE, FALSE, '2026-09-16 21:23:00', '2026-09-16 21:23:00'),
    (221, 78, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 2, FALSE, FALSE, '2026-09-17 00:34:00', '2026-09-17 00:34:00'),
    (222, 5, '혼자 떠나는 짧은 여행 준비 팁을 정리했습니다. 이동 동선, 배터리, 비상 경로까지 실제로 도움이 됐던 내용만 남겼어요. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 26, TRUE, FALSE, '2026-09-17 03:45:00', '2026-09-17 03:45:00'),
