    (262, 45, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 1, FALSE, FALSE, '2026-09-22 03:15:00', '2026-09-22 03:15:00'),
    (263, 2, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-09-22 06:26:00', '2026-09-22 06:26:00'),
    (264, 7, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 13, TRUE, FALSE, '2026-09-22 09:37:00', '2026-09-22 09:37:00'),
    (265, 2, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 6, FALSE, FALSE, '2026-09-22 12:01:00', '2026-09-22 12:01:00'),
    (266, 19, '토마토와 바질을 넣어 가볍게 만든 점심. 재료가 단순할수록 간을 천천히 맞추는 게 중요했다.', NULL, 15, FALSE, FALSE, '2026-09-22 15:12:00', '2026-09-22 15:12:00'),
    (267, 15, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 2, FALSE, FALSE, '2026-09-22 18:23:00', '2026-09-22 18:23:00'),
    (268, 36, '맑은 날보다 흐린 날의 풍경이 더 오래 남을 때가 있다. 오늘은 그런 오후였다.', NULL, 1, FALSE, FALSE, '2026-09-22 21:34:00', '2026-09-22 21:34:00'),
    (269, 44, '오븐에서 갓 나온 빵 냄새는 언제나 과하다 싶을 만큼 좋다. 오늘은 실패 없이 잘 부풀었다.', NULL, 2, FALSE, FALSE, '2026-09-23 00:45:00', '2026-09-23 00:45:00'),
    (270, 5, '평일 저녁 20분 요리 루틴을 파일에 담았습니다. 미리 손질할 재료와 마지막에 넣을 향신료를 나눠두면 맛이 안정됩니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 7, TRUE, FALSE, '2026-09-23 03:09:00', '2026-09-23 03:09:00'),
    (271, 78, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-09-23 06:20:00', '2026-09-23 06:20:00'),
    (272, 6, '해 질 무렵 바닷가를 걸었다. 파도 소리가 크지 않아서 오히려 오래 기억에 남는다.', NULL, 2, FALSE, FALSE, '2026-09-23 09:31:00', '2026-09-23 09:31:00'),
    (273, 2, '골목 끝에서 만난 작은 공원. 벤치 하나와 오래된 나무 그늘만으로 충분히 좋은 쉼표였다.', NULL, 2, FALSE, FALSE, '2026-09-23 12:42:00', '2026-09-23 12:42:00'),
    (274, 26, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 1, FALSE, FALSE, '2026-09-23 15:06:00', '2026-09-23 15:06:00'),
    (275, 5, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 9, FALSE, FALSE, '2026-09-23 18:17:00', '2026-09-23 18:17:00'),
    (276, 5, '구독자용으로 제가 쓰는 산책 코스 기록법을 파일에 정리했습니다. 시간대, 빛 방향, 쉬기 좋은 지점을 함께 적어두면 다음 방문이 훨씬 좋아집니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-23 21:28:00', '2026-09-23 21:28:00'),
    (277, 27, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 1, FALSE, FALSE, '2026-09-24 00:39:00', '2026-09-24 00:39:00'),
    (278, 2, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다.', NULL, 2, FALSE, FALSE, '2026-09-24 03:03:00', '2026-09-24 03:03:00'),
    (279, 2, '동물 사진은 기다리는 시간이 절반이다. 오늘은 눈을 마주친 짧은 순간이 가장 좋았다.', NULL, 2, FALSE, FALSE, '2026-09-24 06:14:00', '2026-09-24 06:14:00'),
    (280, 20, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다.', NULL, 5, FALSE, FALSE, '2026-09-24 09:25:00', '2026-09-24 09:25:00'),
    (281, 25, '오늘 산 능선은 구름이 낮게 걸려 있었다. 같은 길도 날씨가 바뀌면 완전히 다른 풍경이 된다.', NULL, 2, FALSE, FALSE, '2026-09-24 12:36:00', '2026-09-24 12:36:00'),
    (282, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-24 15:00:00', '2026-09-24 15:00:00'),
    (283, 42, '반려견과 걷는 저녁 공원. 같은 길을 매일 가도 냄새를 읽는 속도는 늘 새롭다.', NULL, 1, FALSE, FALSE, '2026-09-24 18:11:00', '2026-09-24 18:11:00'),
    (284, 49, '새벽 호수는 생각보다 조용했다. 물안개가 걷히는 시간을 천천히 담아두었다.', NULL, 2, FALSE, FALSE, '2026-09-24 21:22:00', '2026-09-24 21:22:00'),
    (285, 2, '퇴근길 노을이 좋아서 한 정거장 먼저 내렸다. 오늘의 피로가 조금 옅어지는 색이었다.', NULL, 20, FALSE, FALSE, '2026-09-25 00:33:00', '2026-09-25 00:33:00'),
    (286, 3, '좋았던 문장과 장면을 모아두는 습관이 다시 도움이 되고 있다. 작지만 분명한 저장소다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 10, FALSE, FALSE, '2026-09-25 03:44:00', '2026-09-25 03:44:00'),
    (287, 13, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-09-25 06:08:00', '2026-09-25 06:08:00'),
    (288, 5, '구독자분들께 자주 쓰는 장보기 리스트와 보관 팁을 파일로 올렸습니다. 남는 재료 없이 3일 식단으로 이어지게 구성했습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-25 09:19:00', '2026-09-25 09:19:00'),
    (289, 33, '작은 여행의 기준은 멀리가 아니라 오래 바라볼 장면이 있는가인 것 같다.', NULL, 1, FALSE, FALSE, '2026-09-25 12:30:00', '2026-09-25 12:30:00'),
    (290, 2, '비가 그친 뒤 강변 산책로가 맑게 열렸다. 하늘빛이 물 위에 길게 내려앉아 한참을 서 있었다.', NULL, 7, FALSE, FALSE, '2026-09-25 15:41:00', '2026-09-25 15:41:00'),
    (291, 2, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 2, FALSE, FALSE, '2026-09-25 18:05:00', '2026-09-25 18:05:00'),
    (292, 2, '해 질 무렵 바닷가를 걸었다. 파도 소리가 크지 않아서 오히려 오래 기억에 남는다.', NULL, 1, FALSE, FALSE, '2026-09-25 21:16:00', '2026-09-25 21:16:00'),
    (293, 2, '디저트는 단맛보다 온도가 중요할 때가 있다. 차갑게 식힌 크림과 따뜻한 과일이 잘 맞았다.', NULL, 2, FALSE, FALSE, '2026-09-26 00:27:00', '2026-09-26 00:27:00'),
    (294, 7, '혼자 떠나는 짧은 여행 준비 팁을 정리했습니다. 이동 동선, 배터리, 비상 경로까지 실제로 도움이 됐던 내용만 남겼어요. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 2, TRUE, FALSE, '2026-09-26 03:38:00', '2026-09-26 03:38:00'),
    (295, 2, '주말 아침에는 팬케이크를 구웠다. 반죽을 오래 젓지 않았더니 식감이 훨씬 부드러웠다.', NULL, 8, FALSE, FALSE, '2026-09-26 06:02:00', '2026-09-26 06:02:00'),
    (296, 31, '낯선 동네의 언덕길을 올랐다. 지붕과 전선, 먼 산이 한 장면 안에 차분히 들어왔다.', NULL, 34, FALSE, FALSE, '2026-09-26 09:13:00', '2026-09-26 09:13:00'),
    (297, 15, '가을빛이 들기 시작한 숲길. 발걸음을 늦추니 잎 사이의 작은 소리까지 들렸다. 다음에 다시 가면 같은 자리에서 다른 시간대도 비교해보고 싶다.', NULL, 11, FALSE, FALSE, '2026-09-26 12:24:00', '2026-09-26 12:24:00'),
    (298, 47, '매콤한 파스타에 레몬즙을 조금 더했더니 맛이 또렷해졌다. 작은 산미가 전체를 살린다.', NULL, 1, FALSE, FALSE, '2026-09-26 15:35:00', '2026-09-26 15:35:00'),
    (299, 2, '비 온 뒤 풀밭에서 만난 작은 발자국들. 누가 지나갔는지 상상하는 재미가 있었다.', NULL, 2, FALSE, FALSE, '2026-09-26 18:46:00', '2026-09-26 18:46:00'),
    (300, 5, '구독자용으로 반려동물 산책 체크리스트를 파일에 정리했습니다. 날씨, 물, 리드줄, 귀가 후 발 관리까지 빠뜨리기 쉬운 부분을 담았습니다. 첨부한 Tip.txt에는 바로 따라 할 수 있는 순서와 체크 포인트를 더 자세히 넣었습니다.', '/uploads/files/Tip.txt', 5, TRUE, FALSE, '2026-09-26 21:10:00', '2026-09-26 21:10:00');

