INSERT INTO reply (id, post_id, member_id, content, like_count, hidden, created_at, updated_at) VALUES
    (1, 1, 8, '사진 없이도 아침 공기가 느껴지는 글이네요. 저도 내일은 조금 일찍 나가 봐야겠어요.', 1, FALSE, '2026-09-01 12:01:00', '2026-09-01 12:01:00'),
    (2, 2, 9, '이 시간대에는 사람이 적어서 걷기 정말 좋죠. 선선한 바람까지 부니 부럽습니다.', 1, FALSE, '2026-09-02 12:02:00', '2026-09-02 12:02:00'),
    (3, 3, 10, '이어폰 없이 걸으면 평소 안 들리던 동네 소리가 들려서 좋더라고요.', 1, FALSE, '2026-09-03 12:03:00', '2026-09-03 12:03:00'),
    (4, 4, 11, '저도 같은 길을 자주 걷는데 계절이 바뀔 때마다 분위기가 완전히 달라져요.', 1, FALSE, '2026-09-04 12:04:00', '2026-09-04 12:04:00'),
    (5, 5, 12, '아침에 몸을 조금 움직이면 하루가 훨씬 또렷해지는 느낌이에요.', 1, FALSE, '2026-09-05 12:05:00', '2026-09-05 12:05:00'),
    (6, 6, 13, '비 온 다음 날 산책은 공기부터 다르죠. 글을 읽으니 저도 걷고 싶어졌어요.', 1, FALSE, '2026-09-06 12:06:00', '2026-09-06 12:06:00'),
    (7, 7, 14, '바쁜 아침에도 이런 시간을 챙기는 게 멋져요. 꾸준히 이어 가시길!', 1, FALSE, '2026-09-07 12:07:00', '2026-09-07 12:07:00'),
    (8, 8, 15, '평범한 풍경을 이렇게 잘 발견하는 시선이 좋네요.', 1, FALSE, '2026-09-08 12:08:00', '2026-09-08 12:08:00'),
    (9, 9, 16, '요즘 해 뜨는 시간이 좋아서 아침 산책을 시작하기 딱 좋은 것 같아요.', 1, FALSE, '2026-09-09 12:09:00', '2026-09-09 12:09:00'),
    (10, 10, 17, '천천히 걷는 시간이 생각 정리에도 큰 도움이 되더라고요.', 1, FALSE, '2026-09-10 12:10:00', '2026-09-10 12:10:00'),
    (11, 11, 18, '사진 없이도 아침 공기가 느껴지는 글이네요. 저도 내일은 조금 일찍 나가 봐야겠어요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-11 12:11:00', '2026-09-11 12:11:00'),
    (12, 12, 19, '이 시간대에는 사람이 적어서 걷기 정말 좋죠. 선선한 바람까지 부니 부럽습니다. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-12 12:12:00', '2026-09-12 12:12:00'),
    (13, 13, 20, '이어폰 없이 걸으면 평소 안 들리던 동네 소리가 들려서 좋더라고요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-13 12:13:00', '2026-09-13 12:13:00'),
    (14, 14, 21, '저도 같은 길을 자주 걷는데 계절이 바뀔 때마다 분위기가 완전히 달라져요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-14 12:14:00', '2026-09-14 12:14:00'),
    (15, 15, 22, '아침에 몸을 조금 움직이면 하루가 훨씬 또렷해지는 느낌이에요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-15 12:15:00', '2026-09-15 12:15:00'),
    (16, 16, 23, '비 온 다음 날 산책은 공기부터 다르죠. 글을 읽으니 저도 걷고 싶어졌어요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-16 12:16:00', '2026-09-16 12:16:00'),
    (17, 17, 24, '바쁜 아침에도 이런 시간을 챙기는 게 멋져요. 꾸준히 이어 가시길! 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-17 12:17:00', '2026-09-17 12:17:00'),
    (18, 18, 25, '평범한 풍경을 이렇게 잘 발견하는 시선이 좋네요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-18 12:18:00', '2026-09-18 12:18:00'),
    (19, 19, 26, '요즘 해 뜨는 시간이 좋아서 아침 산책을 시작하기 딱 좋은 것 같아요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-19 12:19:00', '2026-09-19 12:19:00'),
    (20, 20, 27, '천천히 걷는 시간이 생각 정리에도 큰 도움이 되더라고요. 추천하신 조건과도 잘 맞을 것 같아요.', 1, FALSE, '2026-09-20 12:20:00', '2026-09-20 12:20:00'),
    (21, 21, 28, '사진 없이도 아침 공기가 느껴지는 글이네요. 저도 내일은 조금 일찍 나가 봐야겠어요.저도 비슷한 경험이 있어서 더 반갑네요.', 1, FALSE, '2026-09-01 12:21:00', '2026-09-01 12:21:00'),
    (22, 22, 29, '이 시간대에는 사람이 적어서 걷기 정말 좋죠. 선선한 바람까지 부니 부럽습니다.저도 비슷한 경험이 있어서 더 반갑네요.', 1, FALSE, '2026-09-02 12:22:00', '2026-09-02 12:22:00'),
