    (26, 26, 33, '비 온 다음 날 산책은 공기부터 다르죠. 글을 읽으니 저도 걷고 싶어졌어요.저도 비슷한 경험이 있어서 더 반갑네요.', 1, FALSE, '2026-09-06 12:26:00', '2026-09-06 12:26:00'),
