    (33, 33, 40, '이어폰 없이 걸으면 평소 안 들리던 동네 소리가 들려서 좋더라고요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-13 12:33:00', '2026-09-13 12:33:00'),
    (34, 34, 41, '저도 같은 길을 자주 걷는데 계절이 바뀔 때마다 분위기가 완전히 달라져요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-14 12:34:00', '2026-09-14 12:34:00'),
    (35, 35, 42, '아침에 몸을 조금 움직이면 하루가 훨씬 또렷해지는 느낌이에요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-15 12:35:00', '2026-09-15 12:35:00'),
    (36, 36, 43, '비 온 다음 날 산책은 공기부터 다르죠. 글을 읽으니 저도 걷고 싶어졌어요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-16 12:36:00', '2026-09-16 12:36:00'),
    (37, 37, 44, '바쁜 아침에도 이런 시간을 챙기는 게 멋져요. 꾸준히 이어 가시길!나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-17 12:37:00', '2026-09-17 12:37:00'),
    (38, 38, 45, '평범한 풍경을 이렇게 잘 발견하는 시선이 좋네요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-18 12:38:00', '2026-09-18 12:38:00'),
    (39, 39, 46, '요즘 해 뜨는 시간이 좋아서 아침 산책을 시작하기 딱 좋은 것 같아요.나중에 다녀오신 후기도 기다릴게요.', 1, FALSE, '2026-09-19 12:39:00', '2026-09-19 12:39:00'),
